var i=[{title:`Поширені покриття`,text:`Тверда рівна підлога дає стабільну опору для більшості силових рухів. Товстий м’який килим може хитатися під час роботи на одній нозі, а дуже гладка плитка може бути слизькою. Трава чи стежки просто неба можуть бути нерівними та вологими. Килимок робить роботу на підлозі зручнішою, але може ковзати чи стискатися, тож перевірте його, перш ніж ставити на нього великі навантаження.`},{title:`Взуття під завдання`,text:`Стабільне взуття з хорошим зчепленням часто добре підходить для присідів, нахилів і рухів убік. Амортизоване бігове взуття може бути зручним для ходьби чи легкого бігу, але може дозволяти стопі зсуватися під час важких підйомів. Взуття для певних видів спорту відрізняється, і жоден стиль не найкращий для кожної вправи чи кожної людини.`},{title:`Тренування босоніж залежить від обстановки`,text:`Тренування босоніж дає прямий зворотний зв’язок від землі в чистому безпечному просторі, але лишає стопи відкритими до впущених ваг, гострих предметів та інших небезпек. Деякі зали цього не дозволяють. Якщо у вас знижена чутливість стоп, проблеми з рівновагою чи медичний стан стопи, отримайте пораду щодо вашої ситуації перед тим, як тренуватися босоніж, бо це не є автоматично краще.`},{title:`Удар і шум`,text:`Стрибки та біг створюють більше ударів і шуму, ніж контрольовані присіди чи марш. Гумовий килимок може зменшити частину звуку, але вам усе одно потрібні хороше зчеплення та тверда підлога під ним. Уникайте слизьких шкарпеток, хиткої піни під вагами та килимків, що збираються в складки, коли ви ступаєте вбік.`},{title:`Як це працює в TrainUp`,text:`Вкажіть покриття та чи можна стрибати в Профілі, і план добере вправи, що їм відповідають. Якщо підлога слизька чи нерівна, обирайте стабільні вправи з низьким ударним навантаженням або відкладіть рух, доки поверхня не стане безпечною.`}];var l=[{label:`Бібліотека вправ ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: безпека та техніка силових тренувань`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:l};export{r as default,i as sections,l as sources};